1	import { redirect } from 'next/navigation'
2	import { cookies } from 'next/headers'
3	import { createClient } from '@/lib/supabase/server'
4	import { SidebarProvider } from '@/components/ui/sidebar'
5	import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
6	import { AppHeader } from '@/components/app/sidebar/AppHeader'
7	import { PermissionsProvider } from '@/lib/team/permissions-context'
8	import { getUserPermissions } from '@/lib/team/permissions'
9	import { StudioParamSync } from '@/components/shared/StudioParamSync'
10	import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
11	import { getActiveLocation } from '@/lib/context/active-location'
12	import { getActiveMode, getAllowedModes } from '@/lib/context/active-mode'
13	
14	interface AppLayoutProps {
15	  children: React.ReactNode
16	}
17	
18	export default async function AppLayout({ children }: AppLayoutProps) {
19	  const supabase = await createClient()
20	  const {
21	    data: { user },
22	  } = await supabase.auth.getUser()
23	
24	  if (!user) {
25	    redirect('/login')
26	  }
27	
28	  // S15: resolve active studio via cookie (replaces .limit(1).single() pattern)
29	  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
30	  try {
31	    activeStudio = await getActiveStudio()
32	  } catch (err) {
33	    if (err instanceof NoStudioMembershipError) {
34	      redirect('/onboarding')
35	    }
36	    redirect('/onboarding')
37	  }
38	
39	  const { studioId, studio, role, plan, allMemberships } = activeStudio
40	
41	  // S15: resolve active location (depends on studioId — sequential, not Promise.all)
42	  const activeLocation = await getActiveLocation(studioId, role)
43	
44	  // S16B: resolve active mode + allowed modes (parallel-safe with cookie reads)
45	  const [profileResult, permissionsSet, activeMode, cookieStore] = await Promise.all([
46	    supabase.from('profiles').select('full_name, avatar_url').eq('id', user.id).single(),
47	    studioId && user ? getUserPermissions(studioId, user.id) : Promise.resolve(new Set<string>()),
48	    getActiveMode(role),
49	    cookies(),
50	  ])
51	
52	  const allowedModes = getAllowedModes(role)
53	  const permissionKeys = [...permissionsSet]
54	
55	  // Sidebar state from cookie
56	  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'
57	
58	  const profile = profileResult.data
59	  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
60	  const userEmail = user.email ?? ''
61	  const userAvatarUrl = profile?.avatar_url ?? null
62	  const studioName = studio.name
63	  const studioLogoUrl = studio.logo_url ?? null
64	
65	  return (
66	    <PermissionsProvider permissionKeys={permissionKeys}>
67	      {/* S15: StudioParamSync handles ?studio=X deep links — renders null */}
68	      <StudioParamSync currentStudioId={studioId} />
69	      <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
70	        <AppSidebar
71	          locationCount={activeLocation.allLocations.length}
72	          plan={plan}
73	          studioName={studioName}
74	          studioLogoUrl={studioLogoUrl}
75	          role={role}
76	          permissionKeys={permissionKeys}
77	          activeMode={activeMode}
78	          allowedModes={allowedModes}
79	        />
80	        <AppHeader
81	          studioName={studioName}
82	          userName={userName}
83	          userEmail={userEmail}
84	          userAvatarUrl={userAvatarUrl}
85	          role={role}
86	          plan={plan}
87	          allMemberships={allMemberships}
88	          currentStudioId={studioId}
89	          currentLocationId={activeLocation.locationId}
90	          allLocations={activeLocation.allLocations}
91	          permissionKeys={permissionKeys}
92	          activeMode={activeMode}
93	          allowedModes={allowedModes}
94	        >
95	          {children}
96	        </AppHeader>
97	      </SidebarProvider>
98	    </PermissionsProvider>
99	  )
100	}
